 const typeForMode={lock:['lock'],count:['count'],transfer:['transfer','loan'],damage:['damage']},statusText={draft:'草稿',pending_approval:'待审批',active:'生效中',completed:'已完成',released:'已释放',returned:'已归还',rejected:'已驳回',voided:'已作废',in_stock:'在库',outbound:'已出库'},typeText={lock:'库存锁定',count:'库存盘点',transfer:'仓库调拨',loan:'物料借出',damage:'库存报损'};
 const opRows=state.operations.filter(x=>(typeForMode[MODE]||[]).includes(x.operation_type)).filter(x=>!status||x.status===status).filter(x=>!query.trim()||[x.code,x.name,x.source_code,x.counterpart,item(x.sku_id),warehouse(x.source_warehouse_id),warehouse(x.target_warehouse_id)].join(' ').toLowerCase().includes(query.trim().toLowerCase()));
 const serialRows=state.serials.filter(x=>(!status||x.status===status)&&(!query.trim()||[x.code,x.inbound_code,x.outbound_code,item(x.sku_id)].join(' ').toLowerCase().includes(query.trim().toLowerCase())));
 const policy=state.alertPolicies[0]||null,policyValue=(field,fallback)=>policy&&policy[field]!==null&&policy[field]!==undefined?policy[field]:fallback,lowEnabled=policyValue('low_stock_enabled',true)!==false,lowLeadDays=Number(policyValue('low_stock_lead_days',7)),overstockEnabled=policyValue('overstock_enabled',true)!==false,overstockPercent=Number(policyValue('overstock_threshold_percent',120)),slowEnabled=policyValue('slow_stock_enabled',true)!==false,globalSlowDays=Number(policyValue('slow_stock_days',180)),deliveryEnabled=policyValue('delivery_alert_enabled',true)!==false,deliveryDays=Number(policyValue('delivery_warning_days',7)),deliveryUrgentDays=Number(policyValue('delivery_urgent_days',2));
 const ageDays=date=>date?Math.floor((Date.now()-new Date(date).getTime())/86400000):null,recentCutoff=Date.now()-30*86400000,monthlyOutbound=skuId=>state.ledgers.filter(x=>x.sku_id===skuId&&x.direction==='outbound'&&new Date(x.occurred_at).getTime()>=recentCutoff).reduce((sum,x)=>sum+Number(x.quantity||0),0),alerts=state.balances.flatMap(b=>{const result=[],minimum=Number(b.minimum_quantity||0),maximum=Number(b.maximum_quantity||0),dailyUse=monthlyOutbound(b.sku_id)/30,projected=Number(b.available_quantity||0)-dailyUse*lowLeadDays;if(lowEnabled&&minimum>0&&projected<minimum)result.push({kind:'low',label:'低库存',severity:Number(b.available_quantity||0)<minimum?'紧急':'中等',threshold:minimum,balance:b});if(overstockEnabled&&maximum>0&&Number(b.on_hand_quantity||0)>maximum*overstockPercent/100)result.push({kind:'high',label:'超储预警',severity:'中等',threshold:maximum*overstockPercent/100,balance:b});const age=ageDays(b.last_movement_at),slow=Number(b.slow_days||globalSlowDays);if(slowEnabled&&Number(b.on_hand_quantity||0)>0&&age!==null&&age>=slow)result.push({kind:'slow',label:'呆滞库存',severity:'提醒',threshold:slow,balance:b});return result}).filter(x=>(alertKind==='all'||x.kind===alertKind)&&(!query.trim()||[x.label,item(x.balance.sku_id),warehouse(x.balance.warehouse_id)].join(' ').toLowerCase().includes(query.trim().toLowerCase())));
 const orderById=id=>by(state.orders,id),dayDiff=date=>date?Math.ceil((new Date(date+'T23:59:59').getTime()-Date.now())/86400000):99999,deliveryAlerts=(deliveryEnabled?state.orderLines.flatMap(line=>{const order=orderById(line.order_id),remaining=Math.max(0,Number(line.quantity||0)-Number(line.arrived_quantity||0)),due=line.expected_arrival_on||(order&&order.expected_arrival_on),days=dayDiff(due);if(!order||!remaining||['completed','cancelled','rejected'].includes(order.status)||days>deliveryDays)return[];return[{kind:days<0?'overdue':'due',label:days<0?'交期已逾期':'临近交期',severity:days<0||days<=deliveryUrgentDays?'紧急':'提醒',line,order,remaining,due,days}] }):[]).filter(x=>!query.trim()||[x.label,x.order.code,x.line.item_code,x.line.name,by(state.suppliers,x.order.supplier_id)?.name].join(' ').toLowerCase().includes(query.trim().toLowerCase()));
 function toggleLockRow(id){setLockSelected(c=>c.includes(id)?c.filter(x=>x!==id):[...c,id])}function toggleLockAll(){setLockSelected(c=>c.length===lockViewRows.length&&lockViewRows.length>0?[]:lockViewRows.map(x=>x.id))}
