 function openCreate(){if(MODE==='alerts')return setDialog({kind:'alert',step:'form',balance_id:'',minimum_quantity:'0',maximum_quantity:'0',slow_days:String(globalSlowDays),error:''});if(MODE==='sn')return setDialog({kind:'sn',step:'form',code:'',sku_id:'',inbound_code:'',batch_number:'',supplier_id:'',remarks:'',error:''});setDialog({kind:'create',step:'form',operation_type:MODE==='transfer'?'transfer':MODE,document_name:'',balance_id:'',target_warehouse_id:'',quantity:'',actual_quantity:'',source_type:MODE==='lock'?'手动锁库':MODE==='count'?'全盘':MODE==='transfer'?'普通调拨':MODE==='damage'?'损坏':'日常作业',source_code:'',counterpart:'',reason:'',planned_on:today,due_at:'',lock_accounting:false,error:''})}
