 async function create(){setBusy(true);try{validateCreate();if(dialog?.kind==='policy'){const body={name:'默认库存预警设置',code:'INVENTORY-ALERT-DEFAULT',low_stock_enabled:!!dialog.low_stock_enabled,low_stock_lead_days:Number(dialog.low_stock_lead_days),overstock_enabled:!!dialog.overstock_enabled,overstock_threshold_percent:Number(dialog.overstock_threshold_percent),slow_stock_enabled:!!dialog.slow_stock_enabled,slow_stock_days:Number(dialog.slow_stock_days),delivery_alert_enabled:!!dialog.delivery_alert_enabled,delivery_warning_days:Number(dialog.delivery_warning_days),delivery_urgent_days:Number(dialog.delivery_urgent_days),notification_positions:dialog.notification_positions.join(','),remarks:dialog.remarks.trim()||null};await request('/data/forge_inventory_alert_policy'+(policy?'/'+policy.id:''),{method:policy?'PATCH':'POST',body:JSON.stringify(body)});setToast('预警设置已保存并重新计算')}else if(MODE==='alerts'){if(!selectedBalance)throw new Error('请选择仓库物料');await request('/data/forge_inventory_balance/'+selectedBalance.id,{method:'PATCH',body:JSON.stringify({minimum_quantity:Number(dialog.minimum_quantity||0),maximum_quantity:Number(dialog.maximum_quantity||0),slow_days:Number(dialog.slow_days||globalSlowDays)})});setToast('物料预警参数已保存')}else if(MODE==='sn'){if(!dialog.code.trim()||!dialog.sku_id||!dialog.inbound_code.trim())throw new Error('请填写SN码、产品和入库单号');await request('/data/forge_inventory_serial_number',{method:'POST',body:JSON.stringify({name:dialog.code.trim(),code:dialog.code.trim(),sku_id:dialog.sku_id,inbound_code:dialog.inbound_code.trim(),batch_number:dialog.batch_number.trim()||null,supplier_id:dialog.supplier_id||null,status:'in_stock',responsible_id:state.users[0]?.id,remarks:dialog.remarks.trim()||null})});setToast('SN码已登记')}else{if(!selectedBalance)throw new Error('请选择仓库物料');const type=dialog.operation_type,quantity=type==='count'?Number(dialog.actual_quantity):Number(dialog.quantity);if(type!=='count'&&!(quantity>0))throw new Error('数量必须大于0');if(type==='count'&&!(quantity>=0))throw new Error('实盘数量不能小于0');if(type==='count'&&!dialog.document_name.trim())throw new Error('请填写盘点名称');if(!dialog.reason.trim())throw new Error('请填写办理原因');if(type==='transfer'&&!dialog.target_warehouse_id)throw new Error('请选择调入仓库');if(type==='loan'&&!dialog.counterpart.trim())throw new Error('请填写借用方');const code=forgeDocCode(type==='lock'?'LOCK':type==='count'?'CHK':type==='transfer'?'TRF':type==='loan'?'LOAN':'DMG',(state.operations||[]).map(x=>x.code),dialog.planned_on);await request('/data/forge_inventory_operation',{method:'POST',body:JSON.stringify({name:(dialog.document_name.trim()||code+' '+item(selectedBalance.sku_id)),code,operation_type:type,source_warehouse_id:selectedBalance.warehouse_id,target_warehouse_id:dialog.target_warehouse_id||null,sku_id:selectedBalance.sku_id,quantity:type==='count'?Number(selectedBalance.on_hand_quantity):quantity,system_quantity:Number(selectedBalance.on_hand_quantity),actual_quantity:type==='count'?quantity:0,source_type:dialog.source_type,source_code:dialog.source_code.trim()||null,counterpart:dialog.counterpart.trim()||null,reason:dialog.reason.trim(),planned_on:dialog.planned_on,due_at:dialog.due_at||null,lock_accounting:!!dialog.lock_accounting,status:'draft',responsible_id:state.users[0]?.id})});setToast(def.title+'草稿已创建，请在列表继续办理')};setDialog(null);await load()}catch(error){setDialog(d=>({...d,error:String(error.message||error)}))}finally{setBusy(false)}}
 async function invoke(row,action){const params=(dialog&&dialog.params)||{};if(action==='inventory_lock_release'&&!String(params.release_reason||'').trim()){setDialog(d=>({...d,error:'请填写释放原因'}));return}if(action==='inventory_lock_renew'&&!(Number(params.renew_days||0)>0)){setDialog(d=>({...d,error:'请填写有效的续期天数'}));return}if(action==='inventory_lock_void'&&!String(params.void_reason||'').trim()){setDialog(d=>({...d,error:'请填写作废原因'}));return}setBusy(true);try{await request('/actions/forge_inventory_operation/'+action+'/'+row.id,{method:'POST',body:JSON.stringify({params:(dialog&&dialog.params)||{}})});setDialog(null);setToast(action==='inventory_operation_submit'?typeText[row.operation_type]+'已提交审批':action==='inventory_lock_activate'?'库存已锁定':action==='inventory_lock_release'?'库存已释放':action==='inventory_count_complete'?'库存盘点已完成':action==='inventory_loan_return'?'借出物料已归还':typeText[row.operation_type]+'已执行');await load()}catch(error){setDialog(d=>({...d,error:String(error.message||error)}))}finally{setBusy(false)}}
